fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
     .map(|s| {
         if keepends {
             s.split_inclusive('\n')
              .map(|line| line.to_string())
              .collect()
         } else {
             s.split('\n')
              .map(|line| line.to_string())
              .collect()
         }
     })
     .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_splitlines_no_keepends() {
        let input = vec![
            "Hello\nWorld".to_string(),
            "".to_string(),
            "One line".to_string(),
        ];
        let output = splitlines(input, false);
        assert_eq!(output.len(), 3);
        assert_eq!(output[0], vec!["Hello".to_string(), "World".to_string()]);
        assert_eq!(output[1], vec!["".to_string()]);
        assert_eq!(output[2], vec!["One line".to_string()]);
    }

    #[test]
    fn test_splitlines_keepends() {
        let input = vec![
            "Hello\nWorld\n".to_string(),
            "".to_string(),
            "No newline".to_string(),
        ];
        let output = splitlines(input, true);
        assert_eq!(output.len(), 3);
        assert_eq!(
            output[0],
            vec!["Hello\n".to_string(), "World\n".to_string()]
        );
        assert_eq!(output[1], vec!["".to_string()]);
        assert_eq!(output[2], vec!["No newline".to_string()]);
    }
}